<?php require_once 'db.php'; $page_title='Cart'; csrf_check(); if($_SERVER['REQUEST_METHOD']==='POST' && isset($_POST['add'])){$id=(int)($_POST['id']??0);$s=db()->prepare("SELECT id,name,price FROM cakes WHERE id=?");$s->execute([$id]);$item=$s->fetch();if($item){$_SESSION['cart']=$_SESSION['cart']??[];$_SESSION['cart'][$id]=min(10,($_SESSION['cart'][$id]??0)+1);flash($item['name'].' added to cart.');}go('cart.php');} $cart=$_SESSION['cart']??[];$items=[];$total=0;if($cart){$ids=array_map('intval',array_keys($cart));$marks=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT * FROM cakes WHERE id IN ($marks)");$s->execute($ids);$items=$s->fetchAll();} include 'header.php'; ?>
<section class="section"><div class="eyebrow">YOUR BAG</div><h1 style="font-size:3rem">Your cart.</h1><div class="panel table-wrap"><table><thead><tr><th>Item</th><th>Price</th><th>Quantity</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($items as $it): $qty=(int)($cart[$it['id']]??1);$sub=$qty*(float)$it['price'];$total+=$sub; ?><tr><td><?= h($it['name']) ?></td><td>₹<?= number_format($it['price'],2) ?></td><td><?= $qty ?></td><td>₹<?= number_format($sub,2) ?></td><td><a href="book.php?id=<?= (int)$it['id'] ?>">Checkout</a></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="5">Your cart is empty. <a href="catalog.php">Browse the catalog</a>.</td></tr><?php endif; ?></tbody></table><h2 style="margin-top:22px">Total: ₹<?= number_format($total,2) ?></h2><a class="btn" href="catalog.php">Continue shopping</a></div></section><?php include 'footer.php'; ?>